SITUATIONS = [('Practice', 'What is a good daily practice target for {s}?'), ('Revision', 'What is a simple revision routine for {s}?'), ('Mistakes', 'What is the best way to review {s} mistakes?'), ('Questions', 'How should I select practice questions in {s}?'), ('Doubts', 'How should I record doubts in {s}?'), ('Weak Areas', 'How should I choose weak {s} topics for revision?'), ('Mock Tests', 'How should I review a {s} section after a mock?'), ('Accuracy', 'How should I check my {s} answers for accuracy?'), ('Time Management', 'How much time should I give {s} each week?'), ('Exam Strategy', 'How should I approach {s} in a full test?')]

def build():
    out = []
    seen = set()
    def add(cat, q):
        q = q.strip()
        k = q.casefold()
        if q and k not in seen and len(out) < 1000:
            seen.add(k)
            out.append({"Category": cat, "Question": q, "Keywords": q.lower()})
    for cat, q in CORE:
        add(cat, q)
    for subject in SUBJECTS:
        for cat, template in SUBJECT_TEMPLATES:
            add(cat, template.format(s=subject))
    for subject in SUBJECTS:
        for _, context_phrase in CONTEXTS:
            for cat, template in CONTEXT_TEMPLATES:
                add(cat, template.format(s=subject, ctx=context_phrase))
    for _, context_phrase in CONTEXTS:
        for cat, template in GENERAL_CONTEXT_TEMPLATES:
            add(cat, template.format(ctx=context_phrase))
    for subject in SUBJECTS:
        for cat, template in EXTRA_TEMPLATES:
            add(cat, template.format(s=subject))
    for cat, q in GENERAL:
        add(cat, q)
    for subject in SUBJECTS:
        for cat, template in SITUATIONS:
            add(cat, template.format(s=subject))
    assert len(out) == 1000, f"Expected 1000 questions, got {len(out)}"
    assert len({x['Question'].casefold() for x in out}) == 1000
    return out

MOTIVATION = build()
